static void emit(const char *s) {
    if (!emit_enabled) return;
    while (*s) {
        if (*s == '%' && s[1] == '%') {
            fputc('%', output);
            s += 2;
        } else {
            fputc(*s, output);
            s++;
        }
    }
    fputc('\n', output);
}

