static int peek_call_argc(void) {
    char *save_src = input_ptr;
    int save_line = line;
    int save_tok = tok;
    char save_token[MAX_TOKEN_LEN];
    int depth = 0;
    int argc = 0;
    if (tok != '(')
        error("call arity lookahead needs '('");
    safe_strcpy(save_token, token, MAX_TOKEN_LEN);
    next_token();
    if (tok == ')') {
        input_ptr = save_src;
        line = save_line;
        tok = save_tok;
        safe_strcpy(token, save_token, MAX_TOKEN_LEN);
        return 0;
    }
    argc = 1;
    while (tok != T_EOF) {
        if (tok == '(' || tok == '[' || tok == '{') {
            depth++;
        } else if (tok == ')' || tok == ']' || tok == '}') {
            if (depth == 0)
                break;
            depth--;
        } else if (tok == ',' && depth == 0) {
            argc++;
        }
        next_token();
    }
    input_ptr = save_src;
    line = save_line;
    tok = save_tok;
    safe_strcpy(token, save_token, MAX_TOKEN_LEN);
    return argc;
}

