    for (k = 0; k < m - 1 - k; k++) {
        int j = m - 1 - k;
        emit_i("    movq %d(%%rsp), %%r10", k * 8);
        emit_i("    movq %d(%%rsp), %%rax", j * 8);
        emit_si("    movq %s, %d(%%rsp)", "%rax", k * 8);
        emit_si("    movq %s, %d(%%rsp)", "%r10", j * 8);
