static int asm_fixed_home(int c) {
    if (c == 'a') return 0;
    if (c == 'b') return 1;
    if (c == 'c') return 2;
    if (c == 'd') return 3;
    if (c == 'D') return 10;
    if (c == 'S') return 11;
    return -1;
}

static void asm_emit_template(void) {
    char *p = asm_tmpl;
    while (*p) {
        if (*p == '%') {
            p++;
            if (*p == '%') {
                fputc('%', output);
                p++;
            } else if (*p == '=') {
                fprintf(output, "%d", asm_unique);
                p++;
            } else if (*p >= '0' && *p <= '9') {
                int oi = *p - '0';
                p++;
                if (oi < 0 || oi >= asm_nops) error("asm operand number out of range");
                fputs(asm_text[oi], output);
            } else {
                error("unsupported asm template modifier");
            }
        } else {
            fputc(*p, output);
            p++;
        }
    }
    fputc('\n', output);
}

