static int parse_const_int(long long *out) {
    int neg = 0;
    if (tok == '-') { neg = 1; next_token(); }
    else if (tok == '+') { next_token(); }
    if (tok == T_NUM) {
        long long v = safe_strtoll(token);
        next_token();
        *out = neg ? -v : v;
        return 1;
    }
    if (tok == T_ID) {
        int mi = find_macro(token);
        if (mi >= 0) {
            long long v = macros[mi].value;
            next_token();
            *out = neg ? -v : v;
            return 1;
        }
    }
    return 0;
