void mini_puts(const char *s) {
    while (*s) {
        putchar(*s);
        s++;
    }
}

void mini_kprintf(const char *fmt, ...) {
    __builtin_va_list ap;
    __builtin_va_start(ap, fmt);
    while (*fmt) {
        if (*fmt == '%') {
            fmt++;
            if (*fmt == 'd') {
                long v = __builtin_va_arg(ap, long);
                if (v < 0) {
                    putchar(45);
                    v = 0 - v;
                }
                if (v == 0) putchar(48);
                if (v >= 10) {
                    long q = v / 10;
                    if (q >= 10) putchar(48 + q / 10);
                    putchar(48 + q % 10);
                }
                if (v > 0) putchar(48 + v % 10);
            } else if (*fmt == 's') {
                char *s = __builtin_va_arg(ap, char *);
                mini_puts(s);
            } else if (*fmt == '%') {
                putchar(37);
            }
            fmt++;
        } else {
            putchar(*fmt);
            fmt++;
        }
    }
    __builtin_va_end(ap);
}

long vsum(int n, ...) {
    __builtin_va_list ap;
    long total = 0;
    int i = 0;
    __builtin_va_start(ap, n);
    while (i < n) {
        total += __builtin_va_arg(ap, long);
        i++;
    }
    __builtin_va_end(ap);
    return total;
}

